#include <stdio.h>
#include <ctype.h>

int main() {
    int c, count = 0;
    while ((c = getchar()) != EOF) {
        c = tolower(c);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}
